def library_page(title,body,pre):
 s=page(title,body,pre)
 s=s.replace('href="'+pre+'index.html#about">About','href="'+pre+'about/">About').replace('href="'+pre+'Achraf_Rahibe_CV.pdf">Resume</a>','href="'+pre+'index.html#resume">Resume</a>')
 s=s.replace('<a href="'+pre+'technical-notes/">Documents</a>','<a href="'+pre+'blog/">Blog</a><a href="'+pre+'technical-notes/">Documents</a>',1)
 return s
